				\begin{document}$$\:\mathrm{HRR}={\mathrm{HR}}_{\mathrm{max}}-{\mathrm{HR}}_{\mathrm{rest}};\text{Target HR}={\mathrm{HR}}_{\mathrm{rest}}+{\%}\times\:\mathrm{HRR}$$\end{document}

